module fifo_mem #(
    parameter int WIDTH = 8,
    parameter int DEPTH = 4
) (
    input  logic                    clk,

    input  logic                    we,       // write enable
    input  logic [$clog2(DEPTH)-1:0] waddr,
    input  logic [WIDTH-1:0]        wdata,

    input  logic [$clog2(DEPTH)-1:0] raddr,
    output logic [WIDTH-1:0]        rdata     // one cycle after raddr
);

    logic [WIDTH-1:0] store [0:DEPTH-1];

    // The read is written FIRST and with a non-blocking assignment, so
    // it samples what was in the array before this edge. That is what
    // makes a read of the address being written return the old word:
    // every non-blocking right-hand side in the step is evaluated
    // before any of them is applied, so the order of the two
    // statements does not matter — but reading first says the intent.
    always_ff @(posedge clk) begin
        rdata <= store[raddr];
        if (we) store[waddr] <= wdata;
    end

endmodule

// A synchronous FIFO, built on the storage you wrote in milestone 1.
//
// fifo_mem.sv is beside this file and is compiled with it. Instantiate
// it rather than writing another array: the whole point of the
// exercise is the two modules together.

module fifo #(
    parameter int WIDTH = 8,
    parameter int DEPTH = 4
) (
    input  logic             clk,
    input  logic             rst,       // synchronous, active high

    input  logic             wr_en,
    input  logic [WIDTH-1:0] wdata,

    input  logic             rd_en,
    output logic [WIDTH-1:0] rdata,     // valid the cycle after a read

    output logic             full,
    output logic             empty
);

    // your code here — a read pointer, a write pointer, a count, and
    // an instance of fifo_mem. The specification is in the statement:
    // a write is taken when wr_en and not full, a read when rd_en and
    // not empty, and the two may happen on the same edge.

endmodule

