`timescale 1ns/1ps

// The sample testbench. Submit uses another one that drives a
// different depth, resets in the middle, and tries the boundaries
// again.
module tb;

  localparam int W = 8;
  localparam int D = 4;

  logic clk = 1'b0;
  always #5 clk = ~clk;

  logic         rst   = 1'b1;
  logic         wr_en = 1'b0;
  logic         rd_en = 1'b0;
  logic [W-1:0] wdata = '0;
  logic [W-1:0] rdata;
  logic         full;
  logic         empty;

  fifo #(.WIDTH(W), .DEPTH(D)) dut (
    .clk(clk), .rst(rst), .wr_en(wr_en), .wdata(wdata),
    .rd_en(rd_en), .rdata(rdata), .full(full), .empty(empty)
  );

  logic empty_at_reset, not_full_at_reset;
  logic full_after_four, empty_after_all;
  logic [W-1:0] first, second;
  int wrong_order;

  initial begin
    $dumpfile("dump.vcd");
    $dumpvars(0, tb);

    wrong_order = 0;

    @(negedge clk);
    empty_at_reset    = empty;
    not_full_at_reset = !full;
    rst = 1'b0;

    // Four writes fill it.
    @(negedge clk); wr_en = 1'b1; wdata = 8'h11;
    @(negedge clk);               wdata = 8'h22;
    @(negedge clk);               wdata = 8'h33;
    @(negedge clk);               wdata = 8'h44;
    @(negedge clk); wr_en = 1'b0;
    full_after_four = full;

    // A write while full is ignored: the value never appears.
    @(negedge clk); wr_en = 1'b1; wdata = 8'hFF;
    @(negedge clk); wr_en = 1'b0;

    // Read them out, oldest first. rdata is valid the cycle after the
    // edge that took the read.
    @(negedge clk); rd_en = 1'b1;
    @(posedge clk); #1; first = rdata;
    @(posedge clk); #1; second = rdata;
    if (first  !== 8'h11) wrong_order = wrong_order + 1;
    if (second !== 8'h22) wrong_order = wrong_order + 1;
    @(posedge clk);
    @(posedge clk);
    @(negedge clk); rd_en = 1'b0;

    empty_after_all = empty;

    $display("CHECK empty_after_reset 1 %0d AT %0d", empty_at_reset, $time);
    $display("CHECK not_full_after_reset 1 %0d AT %0d", not_full_at_reset, $time);
    $display("CHECK full_after_depth_writes 1 %0d AT %0d", full_after_four, $time);
    $display("CHECK first_in_first_out 0 %0d AT %0d", wrong_order, $time);
    $display("CHECK empty_again_after_reads 1 %0d AT %0d", empty_after_all, $time);
    $display("DONE 5");
    $finish;
  end

endmodule
